SELECT "IdEmpresa","Modulo","CodigoParametro","Valor" FROM (SELECT "IdEmpresa",'PLATAFORMA' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Plataforma.BD::PLA.Configuracion" UNION SELECT "IdEmpresa",'CONTABILIDAD' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Contabilidad.BD::CON.ConfiguracionContabilidad" UNION SELECT "IdEmpresa",'ORDENES' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Orden.BD::ORD.ConfiguracionOrdenes" UNION SELECT "IdEmpresa",'CUENTAINVERSION' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.CuentaInversion.BD::CTA.ConfiguracionCuentaInversion" UNION SELECT "IdEmpresa",'TESORERIA' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Tesoreria.BD::TES.ConfiguracionTesoreria" UNION SELECT "IdEmpresa",'FACTURACION' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Facturacion.BD::FAC.ConfiguracionFacturacion" UNION SELECT "IdEmpresa",'SOCIODENEGOCIO' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.SocioDeNegocio.BD::SOC.ConfiguracionSocioNegocio" UNION SELECT "IdEmpresa",'CUSTODIA' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Custodia.BD::CUS.Configuracion" UNION SELECT "IdEmpresa",'FONDOMUTUO' AS "Modulo","NombreTipoParametro" AS "CodigoParametro","ValorParametro" AS "Valor" FROM "BSCL.FondoMutuo.BD::FMM.Parametro" UNION SELECT "IdEmpresa",'APV' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.APV.BD::PLA.ConfiguracionAPV" UNION SELECT "IdEmpresa",'MESA' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Mesa.BD::MES.ConfiguracionMesa" UNION SELECT "IdEmpresa",'PRODUCTO' AS "Modulo","CodigoParametro","Valor" FROM "BSCL.Plataforma.BD::PRO.Configuracion") WHERE "IdEmpresa" = :IdEmpresa